"""One hundred micro-stories for photo booth strips: (title, opening, development, escalation, payoff).

{a} and {b} are the two participants, and they stay the main characters. Invented extras are fine, but
adults only. Matches can pair strangers, so nothing here is romantic, unkind about anyone's looks,
frightening or dangerous. The second and last beats must stand alone, because 3-frame strips skip the third.
"""
from __future__ import annotations

STORIES: tuple[tuple[str, str, str, str, str], ...] = (
    ("pigeon", "{a} poses proudly, large in the foreground, while {b} stands further back looking up at something above them.", "A pigeon has landed on the head of {a}, who stays deadpan, while {b} leans in from behind and points at it, delighted.", "{b} is close to the lens with a finger to their lips, while behind them {a} stands stiffly with three pigeons on them.", "Pigeons and feathers fill the frame, a blurred feather right at the lens, as {a} ducks at the edge and {b} leans across the foreground laughing."),
    ("bunny ears", "{a} poses formally like a passport photo while {b} leans in from behind, holding up bunny ears behind their head.", "{a} glares sideways at {b}, who has moved to the front with their face close to the lens, grinning.", "{a} now stands behind {b} and holds up bunny ears, looking innocent, while {b} squints suspiciously.", "{a} leans in close to the lens and {b} stays further back, both holding up bunny ears behind each other's heads, overlapping and laughing."),
    ("balloon", "{b} starts blowing up a small red balloon in the foreground while {a} watches calmly from further back.", "A huge red balloon fills the foreground, with {b} still blowing behind it and {a} at the edge of the frame, fingers in their ears.", "The giant red balloon fills most of the frame, with only the wide eyes of {a} and {b} peeking over the top.", "The red balloon bursts into confetti flying at the lens, as {a} and {b} recoil at different distances with shocked faces."),
    ("kitten invasion", "{a} and {b} pose calmly while one tiny kitten sits on the shoulder of {a}.", "Five kittens now climb over {a}, who stays serious, while {b} holds one up to the lens.", "Kittens cover the shoulders and heads of both, one peeking from the collar of {b}.", "A wave of kittens tumbles through the foreground while {a} and {b} laugh, barely visible behind so many paws and tails."),
    ("rubber duck", "{a} holds a small yellow rubber duck up to the camera while {b} looks on, unimpressed.", "A rubber duck the size of a chair pushes into the frame from the left, squeezing {a} against {b}.", "{a} and {b} peek out from behind a yellow rubber duck that fills half the frame.", "Hundreds of yellow rubber ducks rain down around {a} and {b}, who shield their heads and laugh."),
    ("marching band", "{a} and {b} sit still and formal, as a single trumpet bell pokes into the frame from the right.", "A trumpet player in a band uniform blasts into the frame between {a} and {b}, whose hair is blown back.", "A whole marching band in uniform crowds behind {a} and {b}, who are squeezed to the front with their hands over their ears.", "{a} now wears the band leader's tall hat and {b} bangs a big drum in the foreground, with musicians all around them."),
    ("birthday waiter", "{a} and {b} smile politely while a waiter's hand enters from the side carrying a small cupcake.", "A waiter leans in between {a} and {b} with a towering cake, as both stare at it in disbelief.", "The cake tower has grown past the top of the frame and {a} and {b} steady it with both hands, looking panicked.", "The cake topples toward the lens in slow motion, frosting flying, as {a} and {b} lunge in opposite directions."),
    ("banana phone", "{a} holds a banana to their ear like a telephone, very seriously, while {b} watches.", "{b} now answers a second banana in the foreground, shocked by the news, while {a} keeps talking behind them.", "{a} and {b} each hold several bananas to their ears, looking like busy office workers.", "Bananas fly through the air around {a} and {b}, who are shouting into the last banana together and laughing."),
    ("goldfish", "{a} holds a round goldfish bowl in the foreground, with {b} seen distorted through the glass behind it.", "{b} now wears the empty bowl as a helmet, while {a} holds the startled goldfish in a small bag beside their face.", "The bowl is gone and a goldfish floats in mid-air in front of {a}, who stares at it cross-eyed as {b} gapes.", "A school of goldfish swims through the air around {a} and {b}, who reach out for them in wonder."),
    ("disco", "{a} and {b} stand stiffly, as a tiny mirror ball is lowered into the top of the frame.", "A huge mirror ball hangs behind them, throwing light spots as {a} begins a shy dance move and {b} stares.", "{b} strikes a dramatic disco pose in the foreground, one arm high, while {a} copies it badly behind them.", "{a} and {b} dance wildly at different distances, blurred by motion, under a storm of colored light spots."),
    ("indoor snow", "{a} and {b} look up with puzzled faces as one snowflake drifts down between them.", "Snow falls heavily, already piled on the shoulders and heads of {a} and {b}, who stay perfectly still.", "{a} is buried up to the chest in the foreground while {b} digs from behind with a tiny shovel.", "{a} and {b} throw snow at the lens, snow flying everywhere, laughing, with a snowman now standing between them."),
    ("wind machine", "{a} poses glamorously in the foreground, with a gentle breeze moving their hair, while {b} holds a tiny fan.", "{b} now holds a large fan, and the hair and clothes of {a} stream sideways while {a} keeps a dramatic pose.", "Both lean far into a powerful wind at the same angle, hair streaming, with papers flying past them.", "A storm of papers, hats and leaves blows across the frame, as {a} and {b} cling to each other's sleeves and shout with laughter."),
    ("paper planes", "{a} folds a paper plane in the foreground while {b} watches from behind, skeptical.", "A paper plane is stuck in the hair of {b}, who stares at the lens, while {a} looks away, whistling.", "{b} aims a huge paper plane at {a}, who peeks from behind a raised hand.", "Dozens of paper planes fill the air at all depths, one flying right at the lens, as {a} and {b} duck and laugh."),
    ("ufo beam", "{a} and {b} pose normally as a thin beam of green light falls on the hat that {a} is wearing.", "The hat rises off the head of {a} inside a green beam, and {b} points up with an open mouth.", "Now {b} floats a little off the ground in the green beam, arms out, as {a} grabs one of their sleeves.", "A friendly small silver alien peeks into the frame, waving, between the astonished faces of {a} and {b}."),
    ("magician", "{a} wears a top hat and holds a wand while {b} looks on, doubtful, arms crossed.", "{a} pulls a white rabbit from the hat right next to the amazed face of {b}.", "Rabbits sit on the shoulders of {b} and on the top hat, and {a} looks worried and checks the wand.", "White rabbits leap across the whole frame at all depths, as {a} and {b} laugh with their hands in the air."),
    ("mime", "{a} presses both palms against an invisible wall, with a serious face, while {b} watches curiously.", "{b} has joined in, leaning on the same invisible wall from the other side, faces close to it and very determined.", "A mime with white gloves and a striped shirt appears behind them, pulling an invisible rope tied to {a}.", "{a} and {b} are pulled sideways by the invisible rope at a steep angle, as the mime strains and all three laugh."),
    ("detective", "{a} examines {b} through a large magnifying glass in the foreground, and one eye of {a} looks enormous.", "{b} has a magnifying glass too and inspects the nose of {a} very closely, while {a} stares back.", "{a} and {b} wear matching deerstalker hats and peer at a tiny footprint on a card held to the lens.", "A very small dog in a deerstalker hat is revealed as the culprit, held up between the laughing faces of {a} and {b}."),
    ("zero gravity", "{a} and {b} stand normally, but the hair of {a} has started to float upward.", "The hair and clothes of both float upward as {b} rises slightly and {a} grabs for a floating pen.", "{a} floats upside down in the foreground, face still clear, while {b} drifts behind them, amazed.", "{a} and {b} tumble slowly in mid-air at different angles and depths, among floating cups and shoes, laughing."),
    ("underwater", "{a} and {b} stand calmly as a single small bubble rises past the face of {a}.", "A bright tropical fish swims past the nose of {b}, who follows it with their eyes, as bubbles rise around them.", "{a} and {b} have puffed cheeks and wear snorkels while a school of fish swirls between them.", "A big friendly turtle swims through the foreground, with {a} and {b} holding on to its shell and grinning behind it."),
    ("llama", "{a} and {b} pose seriously as the long neck of a llama enters the top corner of the frame.", "A llama looks directly into the lens between {a} and {b}, who slowly turn to look at it.", "The llama chews the collar of {b} while {a} tries, very politely, to reason with it.", "{a} and {b} stand behind the llama with only their faces showing either side of its fluffy neck, all three looking at the camera."),
    ("penguin queue", "{a} and {b} wait side by side as one penguin stands in front of them, looking at the camera.", "A neat line of penguins in the foreground passes in front of {a} and {b}, who look down in disbelief.", "{a} and {b} now shuffle like penguins, arms stiff at their sides, as part of the line.", "Penguins slide past on their bellies in all directions, as {a} and {b} slide too, laughing, near the lens."),
    ("dinosaur toy", "{a} holds a tiny plastic dinosaur to the lens while {b} looks on, bored.", "The dinosaur is now the size of a dog and stands on the shoulder of {a}, as {b} slowly backs away.", "A big friendly green dinosaur head leans into the frame and sniffs the hair of {b}, who stays frozen beside {a}.", "{a} and {b} sit astride a large cartoonish toy dinosaur, cheering, as it charges toward the lens."),
    ("robot vacuum", "A small robot vacuum bumps the foot of {a}, who looks down, while {b} smiles at the camera.", "{b} stands on one leg to dodge the robot vacuum, and {a} holds on to the backdrop for balance.", "A robot vacuum wearing a tiny hat has stolen the shoe of {a}, who points at it, outraged, as {b} laughs.", "A swarm of round robot vacuums spins across the foreground as {a} and {b} jump in the air."),
    ("popcorn", "{a} holds a small bucket of popcorn while {b} reaches for one piece from behind.", "One kernel bounces off the forehead of {b} as popcorn starts popping out of the bucket held by {a}.", "A fountain of popcorn erupts from the bucket, and {a} and {b} try to catch it in their mouths.", "{a} and {b} are chest deep in popcorn in the foreground, with more falling all around, laughing."),
    ("toaster", "{a} holds a shiny toaster while {b} waits, with a plate and a very serious face.", "A slice of toast shoots up past the surprised face of {b}, while {a} looks into the toaster.", "Toast flies in all directions, and {b} catches one slice with their teeth as {a} holds up a plate.", "{a} and {b} wear slices of toast like glasses and hold up a giant slice with their faces poking around it."),
    ("giant pizza", "{a} offers a normal slice of pizza to {b}, both looking very formal.", "The slice has become as big as a door, and {a} and {b} each hold one end of it, struggling.", "Stretchy cheese connects {a} and {b} across the foreground as they back away from each other, puzzled.", "{a} and {b} peek through two pepperoni-sized holes in an enormous pizza that fills the whole frame."),
    ("tiny photographers", "{a} and {b} look down at something small on the hand of {a}, in the foreground.", "A tiny person with a tiny camera on the hand of {a} takes a photo, and {b} leans in close, amazed.", "Tiny people in suits hold tiny cameras on the shoulders of {a} and {b}, who hold perfectly still.", "A crowd of tiny photographers on the heads and arms of {a} and {b} fires tiny flashes as both laugh."),
    ("stilts", "{a} and {b} stand at the same height, looking at the camera, with a pair of stilts leaning nearby.", "Only the chest and head of {b} are visible as they lean far down from stilts, next to {a}, who looks up.", "{a} now towers on stilts above the frame edge, leaning down so their head comes in upside down beside {b}.", "{a} and {b} wobble dangerously on stilts at wild angles, faces close to the lens, laughing."),
    ("superheroes", "{a} ties a small red cape on, very seriously, while {b} watches with a raised eyebrow.", "{a} strikes a heroic pose in the foreground, cape flying, while {b} has a tea towel tied around their neck.", "{b} now stands in a heroic pose in the foreground, with an even bigger cape, while {a} is tangled up in theirs.", "{a} and {b} fly across the frame at different depths, capes streaming, fists forward, with paper stars around them."),
    ("parrot", "A colorful parrot sits on the shoulder of {a}, who poses in a pirate hat, while {b} looks skeptical.", "The parrot has moved to the head of {b} and squawks at the lens, while {a} looks betrayed.", "The parrot wears the pirate hat now, as {a} and {b} both offer it crackers with pleading faces.", "Parrots of every color flap through the foreground, as {a} and {b} laugh with crackers in their hands."),
    ("pancakes", "{a} holds a frying pan with a pancake in the foreground, ready to flip it, while {b} looks up.", "The pancake flies high above them while {a} and {b} look up, mouths open, tracking it.", "The pancake has landed on the face of {b}, showing only one eye, while {a} tries hard not to laugh.", "Pancakes spin through the air at all depths, with {a} catching them on a tall stack and {b} wearing one as a hat."),
    ("paint fight", "{a} holds a clean paintbrush up to the cheek of {b}, who eyes it with suspicion.", "{b} has one blue stripe on their nose and stares at the lens, while {a} hides the brush behind their back.", "Both have colorful stripes on their cheeks and hold up large brushes like conductors, grinning.", "Bright paint splashes across the lens edge and the air around {a} and {b}, who are laughing and speckled with color."),
    ("mirror twins", "{a} and {b} stand beside a tall mirror, looking at their reflections with mild interest.", "The reflection of {a} is doing something else: it waves while the real {a} stands still, and {b} points at it.", "The reflection of {b} has stepped halfway out of the mirror and taps the real {b} on the shoulder, as {a} gapes.", "Two copies of {a} and two copies of {b} crowd together at different depths, all laughing and pointing at each other."),
    ("shadow puppets", "{a} makes a small rabbit-shaped hand shadow on the backdrop while {b} watches.", "A huge shadow of a dog chases the rabbit across the backdrop, cast by the hands of {b} in the foreground.", "The shadow dog has bitten a shadow sandwich, while {a} looks at their real empty hand, confused.", "Giant shadow animals with lives of their own surround {a} and {b}, who cling together in comic alarm, laughing."),
    ("hot air balloon", "{a} and {b} stand in a small wicker basket, as ropes rise out of the top of the frame.", "The basket lifts off, and {a} leans out into the foreground with binoculars while {b} holds on, eyes shut.", "Small clouds drift past the faces of {a} and {b}, and a bird lands on the basket rim.", "{a} and {b} wave from the rising basket, with sandbags falling and tiny clouds drifting past them."),
    ("surprise party", "{a} and {b} sit quietly in dim light, unaware of hands poking in at the bottom of the frame.", "Several adults in party hats jump up behind {a} and {b}, who flinch, with paper streamers in mid-air.", "{a} and {b} wear party hats, as a stranger pushes a gift box the size of a chair toward them.", "The gift box bursts open with a shower of confetti in the foreground, and everyone cheers around {a} and {b}."),
    ("opera", "{a} clears their throat with one hand on their chest, while {b} prepares to listen politely.", "{a} sings with their mouth wide open and {b} is blown slightly back, hair lifted by the sound.", "A grand opera singer in a costume appears behind them, and {a} and {b} look at each other in alarm.", "{a}, {b} and the opera singer all sing at full volume at different depths, with cracked glasses flying in the air."),
    ("glitter sneeze", "{a} is about to sneeze, eyes squeezed and head back, while {b} leans in with concern.", "{a} sneezes a cloud of gold glitter that hits {b}, who stays frozen with their eyes shut.", "{b} is covered in glitter and slowly opens one eye, as {a} covers their mouth, horrified.", "{b} sneezes back, and a huge burst of glitter fills the frame, with both faces shining and laughing through it."),
    ("scarf tug", "{a} and {b} are each holding one end of a long striped scarf, looking at each other.", "{a} leans back pulling at a sharp angle, while {b} is dragged toward the lens, grinning.", "The scarf is now wrapped around both heads like a turban, and both stare ahead, confused.", "{a} and {b} are tangled in an impossibly long scarf that fills the frame in stripes, with only their laughing faces showing."),
    ("sunflower", "{a} holds a small flowerpot with a sprout in the foreground while {b} pours a little water.", "A tall sunflower has grown through the frame, and its big face looks at {a} and {b}, who look back.", "Sunflowers crowd the frame, with {a} and {b} peeking between the stalks at different depths.", "A huge sunflower head rests on {b} like a hat, and {a} wears a ring of petals, both laughing among the leaves."),
    ("jungle vines", "One green vine drops into the frame beside {a}, who ignores it while {b} stares at it.", "Vines curl around the arms of {a} and {b}, who look at each other, with leaves sprouting all around.", "{a} swings through the foreground on a vine, a blur with a clear happy face, as {b} ducks.", "{a} and {b} peer out through dense jungle leaves, with a monkey wearing a tiny hat sitting on the head of {b}."),
    ("yarn", "{a} holds a large ball of red yarn while {b} holds their hands out to help wind it.", "A strand of red yarn loops around the neck of {b}, while {a} looks away, innocently still winding.", "Red yarn crisscrosses the whole frame like a web, with {a} and {b} caught at different depths.", "A big fluffy cat sits in the foreground looking pleased, while {a} and {b} are wrapped in yarn behind it, laughing."),
    ("butterflies", "A single blue butterfly rests on the nose of {a}, who goes cross-eyed, while {b} watches, holding their breath.", "Butterflies land on the head and shoulders of {b}, who stays still, while {a} slowly raises a finger.", "Butterflies form a colorful crown on {a} and a moustache on {b}, as both try not to laugh.", "A cloud of butterflies lifts off at once, swirling toward the lens around the laughing faces of {a} and {b}."),
    ("frog hat", "{a} wears a neat hat and poses seriously, with a green frog sitting on top, while {b} has noticed it.", "The frog has jumped to the nose of {b}, who stares at it cross-eyed, while {a} feels the top of their hat.", "{a} holds up the hat to catch the frog, which is in mid-leap across the foreground, as {b} ducks.", "Green frogs jump in all directions at all depths, as {a} and {b} try to catch them in their hats, laughing."),
    ("owl", "{a} and {b} pose as an owl on a perch behind them stares straight at the camera.", "The owl has moved to the shoulder of {a}, and all three turn their heads at the same angle toward {b}.", "{b} wears big round owl glasses and stares back at the owl, nose to beak, as {a} watches, delighted.", "Three owls in glasses sit on {a} and {b}, and everyone stares wide-eyed into the lens."),
    ("dog thief", "{a} and {b} wear matching hats as a dog's nose enters the frame at the bottom.", "A big happy dog leaps up between them, with the hat of {a} in its mouth, as {a} grabs at the air.", "The dog now wears the hat, sitting in the foreground, while {a} and {b} kneel behind it and plead.", "The dog licks the lens, its nose huge and blurred, with {a} and {b} laughing behind it."),
    ("sloth", "{a} and {b} look at the camera as a sloth hangs at the very top edge of the frame.", "The sloth has moved a little lower, smiling, its long claw just touching the hair of {b}, who has not noticed.", "The sloth hangs with its face right next to {a}, who turns very slowly, while {b} stares in amazement.", "{a} and {b} hang their heads to the side in the same slow pose as the smiling sloth between them, all at peace."),
    ("giraffe", "{a} and {b} look at the camera, with a very long spotted neck rising behind them out of the frame.", "A giraffe's head comes down from above and looks at {a} and {b} upside down, chewing.", "The giraffe's long tongue steals the sandwich held by {b}, while {a} laughs behind their hand.", "The giraffe's head fills the foreground in close-up, with {a} and {b} small and laughing behind its huge eyelashes."),
    ("elephant trunk", "{a} and {b} sit formally as a gray elephant trunk slides into the frame from the right.", "The trunk has lifted the hat of {b} and waves it, and {a} points at it, delighted.", "The trunk sprays a gentle shower of water over {a}, while {b} holds up a small umbrella.", "A baby elephant squeezes in between {a} and {b}, ears wide, as all three look at the camera, soaking wet."),
    ("octopus", "{a} and {b} pose as one orange tentacle reaches up from the bottom of the frame.", "Tentacles hold up a comb, a mirror and a teacup around {a}, who looks flattered, while {b} is alarmed.", "A tentacle puts glasses on {b} and straightens the collar of {a}, as both sit very still.", "A cheerful orange octopus sits between {a} and {b}, with an arm around each of their props, all posing like a family portrait."),
    ("indoor rain", "{a} holds out a hand to check for rain, while {b} looks at the ceiling, frowning.", "Rain pours down inside the booth, with {a} holding a tiny umbrella and {b} completely drenched.", "{b} has put on a yellow rain hat, and {a} is wringing water from their sleeve in the foreground.", "{a} and {b} stomp and splash in rubber boots, water flying toward the lens, laughing in the rain."),
    ("light bulb", "{a} and {b} think hard, chins on their hands, in a dim booth.", "A glowing light bulb appears above the head of {a}, who lights up, while {b} squints at it.", "{b} has a bigger light bulb, and {a} looks jealous, trying to screw in a larger one.", "Dozens of glowing bulbs float around {a} and {b}, whose faces are bright with a brilliant idea."),
    ("tiny piano", "{a} sits at a toy piano in the foreground, very serious, as {b} prepares to turn the pages.", "{a} plays with wild passion, hair flying, while {b} holds up a page and is moved to tears.", "A tall stranger in a tuxedo leans in behind them, playing a tiny violin, as {b} conducts with a breadstick.", "Music notes burst from the tiny piano across the frame, while {a} and {b} bow deeply toward the lens."),
    ("trumpet blast", "{a} lifts a shiny trumpet in the foreground and takes a breath, while {b} covers their ears ahead of time.", "One note blows the hair of {b} straight back, while {a} looks pleased behind the trumpet.", "{b} has a giant tuba now, nearly hiding them, and blows it back at {a}, whose cheeks ripple.", "Both blast instruments in a storm of paper notes, at different distances from the lens, eyes shut, laughing."),
    ("drum solo", "{a} holds up two drumsticks, very focused, while {b} looks at them doubtfully.", "{a} is a blur of drumsticks with hair flying, and {b} is bouncing slightly with a drum in front of them.", "The drumsticks have multiplied, with {b} holding four and {a} holding six, both utterly serious.", "A cymbal flies past the lens, as {a} and {b} leap with their sticks in the air, faces ecstatic."),
    ("karaoke", "{a} grips a microphone with both hands in the foreground, nervous, while {b} gives a small thumbs up.", "{a} sings with their eyes shut while {b} pretends to play air guitar behind them.", "{b} has grabbed the microphone and is on one knee in the foreground, as {a} waves a lighter-shaped toy.", "{a} and {b} sing into one microphone, faces close to the lens, as paper stars and strangers' waving hands fill the frame."),
    ("lasso", "{a} wears a cowboy hat and twirls a rope in a small circle above their head, while {b} watches.", "The rope has fallen neatly around {b}, who looks down, surprised, as {a} tips their hat.", "{b} wears the cowboy hat now, and {a} is the one tied up, as a toy horse peeks in at the side.", "{a} and {b} ride a bouncing toy horse at an angle, hats flying off and ropes looping through the air."),
    ("chess", "{a} and {b} stare intently at a chessboard held in the foreground, each with a hand on their chin.", "{a} makes a move with a flourish, while {b} leans in very close to the board with a horrified face.", "{b} is now sneakily moving a piece while {a} looks away, and a tiny knight looks up at the lens.", "Chess pieces fly up from the flipped board toward the lens, with {a} and {b} behind them, shouting with laughter."),
    ("card trick", "{a} fans a deck of cards in the foreground and asks {b} to pick one, and {b} takes it, suspicious.", "{a} pulls the card from behind the ear of {b}, who looks at it, stunned.", "Cards are stuck in the hair and collar of {b}, and {a} is pulling a very long string of them from their sleeve.", "A fountain of playing cards fills the air at all depths, as {a} and {b} throw their hands up, laughing."),
    ("juggling", "{a} holds up three oranges, confident, while {b} stands by, watching with folded arms.", "Three oranges hang in the air above {a}, who is focused, while {b} sneaks a fourth into the air.", "{a} juggles oranges, a rubber chicken and a shoe, sweating, while {b} keeps adding more from a basket.", "Everything falls at once around {a} and {b}, oranges bouncing toward the lens, as both duck and laugh."),
    ("yo-yo", "{a} shows a small yo-yo in the foreground, with a serious expert face, while {b} watches.", "The yo-yo has looped around the nose of {b}, who stands still, as {a} winces.", "{b} is tangled in yo-yo string while {a} tries to untie it with a very serious face.", "Yo-yos on strings come down from above all around {a} and {b}, who try to bat them away, laughing."),
    ("hula hoops", "{a} holds a bright hula hoop and looks confident, while {b} holds one and looks doubtful.", "{a} spins the hoop with intense concentration, and {b} is framed through a second hoop, watching.", "Six hoops spin around {b}, who is amazed, while the one held by {a} has fallen to the floor.", "A blur of colored hoops crosses the frame at all depths, with {a} and {b} spinning and laughing inside them."),
    ("giant bubbles", "{a} dips a wand in soap while {b} leans in, curious, and a small bubble floats between them.", "A huge soap bubble floats in the foreground, with the face of {b} distorted through it next to {a}.", "{a} and {b} are both inside one giant shimmering soap bubble, looking out in wonder.", "The giant bubble pops around them in a burst of droplets, with {a} and {b} blinking and laughing, soap in their hair."),
    ("bowling", "{a} holds a bowling ball near the lens with a focused squint, as {b} stands far behind them.", "{b} stands among tall bowling pins, holding two of them, looking worried about what is coming.", "A bowling ball rolls large through the foreground, with {a} watching it, hands clasped, and {b} covering their eyes.", "Bowling pins fly in every direction as {b} leaps through the air and {a} throws up both arms, cheering."),
    ("ping-pong", "{a} and {b} hold ping-pong paddles at the ready, staring each other down.", "A white ball hangs in the air in front of the lens, as {a} and {b} lunge from either side, eyes on it.", "A ball has stuck to the forehead of {b}, and {a} slowly lowers their paddle, puzzled.", "Hundreds of ping-pong balls bounce through the frame at all depths, with {a} and {b} batting wildly and laughing."),
    ("beach ball", "{a} holds a big striped beach ball in the foreground, wearing sunglasses, with {b} behind them in a sun hat.", "The beach ball bounces off the head of {b}, whose sun hat flies up, as {a} looks away, innocent.", "{a} and {b} both leap for the ball, faces close together with arms stretched high.", "Beach balls drop from above, along with sand and a stranger on an inflatable flamingo, as {a} and {b} laugh."),
    ("skateboard", "{a} and {b} pose quietly as a skateboard rolls in by itself along the bottom of the frame.", "A stranger on a skateboard flies through the frame behind {a} and {b}, who are looking the wrong way.", "{a} now wobbles on the skateboard, arms wide, as {b} holds on to their sleeve and looks worried.", "{a} and {b} rush toward the lens together on one skateboard, hair flying, wide-eyed and shouting."),
    ("roller skates", "{a} sits lacing up bright roller skates in the foreground while {b} stands, slightly unsteady, behind them.", "{b} rolls slowly backward out of the frame with a calm face, reaching out, while {a} stares.", "{a} glides past in the foreground, one leg raised, while {b} clings to the edge of the booth.", "{a} and {b} spin at speed holding each other's sleeves, a blur of skates, faces clear and laughing."),
    ("tiny car", "{a} holds a tiny toy car in the foreground and makes engine noises while {b} watches, deadpan.", "A small red pedal car has appeared, and {a} and {b} are squeezed into it with their knees up to their chins.", "{b} is honking a horn, and {a} studies a huge map that covers most of the frame.", "The little car speeds at the lens with {a} and {b} hanging on, scarves streaming, shouting with joy."),
    ("train conductor", "{a} wears a conductor's hat and checks a pocket watch, while {b} waits with a small suitcase.", "A toy train runs along the shoulders of {b}, who stays still, as {a} blows a whistle.", "A crowd of adult commuters squeezes in around {a} and {b}, who are pressed into the foreground.", "Steam fills the frame, with {a} leaning out of a toy locomotive and {b} waving a handkerchief, both laughing."),
    ("mail avalanche", "A hand passes one envelope to {a}, who opens it calmly while {b} looks over their shoulder.", "Envelopes pour in from above, and {a} and {b} try to sort them with very serious faces.", "{a} is buried up to the neck in letters in the foreground, while {b} reads one out loud behind them.", "A storm of letters flies at the lens, with a postal worker peeking in, as {a} and {b} laugh and throw handfuls."),
    ("laundry", "{a} and {b} pose calmly as one sock hangs from a line that crosses the frame.", "Laundry has filled the line, with a shirt falling over the head of {b}, while {a} holds a clothes peg.", "{a} has clothes pegs on their sleeves, and {b} peeks through the neck of a giant sweater.", "A big sheet blows across the foreground in the wind, and {a} and {b} burst through it, laughing."),
    ("ice cream tower", "{a} holds a cone with one scoop of ice cream in the foreground, while {b} adds a second.", "The tower of scoops has grown above the frame, with {a} leaning to balance it and {b} guiding it, worried.", "{b} licks from one side and {a} from the other side of the wobbling tower, eyes meeting in panic.", "Scoops of ice cream fall through the frame in slow motion, as {a} and {b} try to catch them in cones."),
    ("watermelon", "{a} holds a huge watermelon in their arms in the foreground, proudly, while {b} holds a tiny spoon.", "{b} takes a big bite of a slice as wide as their face, while {a} holds up another, grinning.", "{a} and {b} have watermelon slices in front of their mouths, as big green smiles.", "Watermelon seeds fly toward the lens as {a} and {b} spit them at a tiny target, laughing, cheeks full."),
    ("cupcake", "{a} holds up a perfect cupcake, while {b} looks at it hungrily.", "A blob of frosting sits on the nose of {b}, and {a} looks away, holding an empty spoon.", "{a} now has frosting on their chin and in their hair, and {b} is holding the piping bag, looking satisfied.", "Colored frosting and sprinkles fly through the air around {a} and {b}, sprinkles blurred right at the lens."),
    ("spilled coffee", "{a} carries a full coffee cup, walking carefully in the foreground, while {b} looks at the camera.", "The coffee has left the cup and hangs frozen in mid-air in front of the startled {a} and {b}.", "{b} slowly slides a saucer under the floating coffee, with an extremely careful face, as {a} holds their breath.", "The coffee splashes into the cup and overflows into many cups held by {a} and {b}, who laugh with relief."),
    ("frozen time", "{a} holds up a large alarm clock, tapping it, while {b} checks a wristwatch.", "{a} has frozen mid-sneeze with hair in the air, and {b} walks around them, waving a hand before their face.", "{b} has balanced a stack of cups on the frozen {a}, and adds a paper hat with great care.", "Time restarts: cups fall all around as {a} jumps in shock and {b} tries to catch them, laughing."),
    ("time travel", "{a} and {b} stand in a shimmer of light, in their normal clothes, looking at their hands.", "{a} now wears a Victorian top hat and {b} a huge ruff collar, both looking at each other in surprise.", "{a} wears a shiny silver space suit, and {b} wears a powdered wig, with clocks floating behind them.", "{a} and {b} spin through a swirl of clocks, hats and gears at different depths, their costumes flying off."),
    ("friendly ghost", "{a} and {b} pose, not seeing a small white sheet with two eye holes behind them.", "A sheet ghost peeks over the shoulder of {a}, while {b} slowly begins to turn.", "{b} has thrown up their hands, and the ghost has done the same, as if scared of {b}, while {a} stares.", "{a} and {b} wear sheets too, pulled back to show their laughing faces, standing beside the ghost in a row."),
    ("wizard", "{a} wears a tall pointed hat and holds up a stick as a wand, while {b} holds a book, unconvinced.", "Sparks fly from the wand, turning the hat of {b} into a bunch of flowers, as {b} looks up.", "The spell has gone wrong, and {a} now has a long white beard, as {b} flips through the book, panicking.", "Stars and sparks whirl around {a} and {b} at all depths, and a small dragon flies through the foreground."),
    ("genie lamp", "{a} polishes a small golden lamp in the foreground, while {b} leans in to look.", "A swirl of blue smoke rises from the lamp, and {a} and {b} lean back, wide-eyed.", "A large friendly genie with a beard floats behind them, an arm above each, offering a very long menu.", "Gold coins, crowns and sandwiches rain down in the frame, as {a} and {b} laugh and the genie takes a photo."),
    ("treasure map", "{a} holds up a torn treasure map in the foreground, and {b} peers at it, holding a lantern.", "{a} points off to one side while {b} points the opposite way, the two arguing with serious faces.", "{a} and {b} look down into a hole in the foreground, and only their faces show at its rim.", "A chest bursts open at the lens, spilling golden light onto the astonished, laughing faces of {a} and {b}."),
    ("mummy", "{a} holds a small roll of white bandage, and {b} holds out one arm, ready to help.", "An arm of {b} is wrapped entirely in white strips, with {a} working with great concentration.", "{b} is wrapped up to the chin, with a clear face and a resigned look, and {a} proudly shows the result.", "{a} is now tangled up too, with both unwinding at speed, white strips looping all around the frame."),
    ("museum statue", "{a} poses like a marble statue on a small plinth, while {b} studies them, with a museum guide in hand.", "{a} secretly scratches their nose the moment {b} turns away to read the guide.", "{b} peers closely with a magnifying glass, and {a} holds their breath, one eye half open.", "{a} and {b} both pose on the plinth while a confused museum guard in uniform takes notes in the foreground."),
    ("picture frame", "{a} holds up an empty golden picture frame around their own face, with a serious expression, while {b} looks on.", "{b} is now inside the frame in the foreground, posing like an old portrait, while {a} adjusts it.", "{a} and {b} both squeeze their faces into one small golden frame, cheeks pressed against its edges.", "Golden frames of all sizes hang in the air at all depths, with {a} and {b} posing in different ones, laughing."),
    ("newspaper", "{a} reads a huge newspaper that hides everything but their eyes, while {b} sits calmly beside them.", "A finger from {b} pokes through the newspaper, and {a} looks at it over the top, offended.", "{a} and {b} both look out of two holes in the newspaper, in a detective's disguise.", "The sheets fly apart across the frame like a flock of birds, as {a} and {b} grab at them and laugh."),
    ("flying books", "{a} holds up an open book in the foreground and reads solemnly, while {b} looks over the top.", "A second book flaps past like a bird, as {a} keeps reading and {b} tracks it, mouth open.", "Books perch on the shoulders of {b}, and one has opened on the head of {a}, who hasn't noticed.", "Books flap through the air in all directions at all depths, pages flying, as {a} and {b} duck and laugh."),
    ("telephone cord", "{a} answers an old telephone with a long curly cord in the foreground, while {b} holds the base.", "{a} hands the receiver to {b}, whose eyes grow wide at the news, as the cord loops between them.", "The curly cord is now wrapped all around both, with both speaking into the receiver at once.", "Dozens of telephones ring and dangle by their cords all around {a} and {b}, who answer two at once, laughing."),
    ("rival camera", "{b} holds up a phone on a selfie stick in the foreground, while {a} tries to get into the shot.", "{b} poses with the phone, unaware that {a} is making a very odd face right behind them.", "A paparazzi crowd of adults with cameras pushes in behind them, as {a} and {b} shield their eyes.", "Flashes burst all around, and {a} and {b} strike movie star poses in dark glasses, with paper stars falling."),
    ("old photographer", "A photographer's black cloth and old wooden camera appear at one side, while {a} and {b} sit stiffly.", "A stranger in an old-fashioned suit peeks from under the cloth, while {a} and {b} hold a formal pose.", "A flash tray has gone off in a puff of white smoke, leaving {a} and {b} blinking with sooty noses.", "{a} is now under the cloth, with {b} and the old photographer posing stiffly and trying not to laugh."),
    ("yoga", "{a} stands calmly in a simple yoga pose in the foreground, while {b} tries to copy it behind them.", "{b} has fallen slightly out of the pose, leaning into {a}, who has their eyes shut, serene.", "A yoga teacher in a headband gently adjusts {b} into an odd shape, while {a} opens one eye to look.", "{a} and {b} tip over at an angle like dominoes, at different distances from the lens, laughing."),
    ("strongperson", "{a} tries to lift a tiny dumbbell in the foreground with great effort, while {b} cheers them on.", "{b} holds a huge cartoonish barbell with weights marked with very large numbers, lifting it with one finger.", "A cheerful circus strongman in a striped suit appears behind them and flexes, and {a} and {b} copy him.", "The huge weights turn out to be balloons, floating off and lifting {a} and {b} slightly, both laughing."),
    ("ballet", "{a} stands on tiptoe with arms in a graceful circle in the foreground, while {b} watches respectfully.", "{b} joins with a very wobbly leap behind {a}, with a tutu around their waist.", "A real ballet dancer in costume leaps across the frame above {a} and {b}, who look up, stunned.", "{a} and {b} spin in tutus at different depths, among falling paper roses, arms flung out and laughing."),
    ("conga line", "{a} and {b} look at the camera as a hand reaches into the frame and rests on the shoulder of {a}.", "A line of cheerful adults in party clothes dances through the frame behind {a} and {b}, who look back.", "{a} and {b} have joined the line, one behind the other, kicking out to one side at an angle to the lens.", "The conga line curls around the frame from foreground to background, with {a} and {b} leading it, shouting with joy."),
    ("falling backdrop", "{a} and {b} pose in front of the plain backdrop, one corner of which has started to peel.", "The backdrop is falling over {b}, while {a} reaches up to hold it with one hand, still smiling for the camera.", "{a} and {b} are both under the sagging backdrop, with only their faces poking out of a tear in it.", "A second backdrop of the same color falls behind the first with a puff of dust, as {a} and {b} escape toward the lens, laughing."),
    ("pillow fight", "{a} holds a soft pillow behind their back with an innocent smile, while {b} looks at the camera.", "A pillow hits the side of the head of {b}, whose hair flies up, while {a} looks away, whistling.", "{b} has two pillows raised high in the foreground, and {a} peeks out from behind a very small cushion.", "Feathers fill the whole frame at all depths, with {a} and {b} swinging pillows and laughing."),
    ("sock puppets", "{a} wears a striped sock puppet on one hand, and it stares at {b}, who stares back.", "The puppet whispers in the ear of {b}, who looks shocked, while {a} acts as if nothing is happening.", "{b} now has a puppet too, and the two puppets argue in the foreground while {a} and {b} look away.", "Sock puppets pop up on many hands from below the frame around {a} and {b}, who laugh, outnumbered."),
    ("personal cloud", "A tiny gray cloud floats above the head of {b}, who hasn't noticed, while {a} points at it.", "The tiny cloud rains only on {b}, who stands dripping and deadpan beside the perfectly dry {a}.", "{a} holds a tiny umbrella up over {b}, and the little cloud has moved over to {a}, who looks up slowly.", "The cloud bursts into a tiny rainbow between {a} and {b}, who are soaked, laughing and pointing at it."),
    ("signpost", "{a} holds up a wooden signpost with many arrows in the foreground, while {b} studies a very small map.", "{a} points left and the map held by {b} points right, as they look at each other, confused.", "A hiker with a huge backpack leans in between {a} and {b}, pointing straight at the lens.", "Arrows, maps and compasses whirl through the air around {a} and {b}, who march toward the lens in opposite directions, laughing."),
    ("vending machine", "{a} holds up a single coin in the foreground, very seriously, while {b} waits behind them, hungry.", "A snack dangles in a vending machine behind them, and {a} and {b} stare at it with their faces against the glass.", "{b} is shaking the machine in the background while {a} reaches an arm inside, with a look of total focus.", "The vending machine bursts open and snacks pour past the lens, as {a} and {b} catch them in their arms, laughing."),
)
